function _agentStatus(st) {
  if (!st || !st.status || st.status === "pending") return {
    t: "ждёт",
    c: "var(--ink-4)",
    run: false
  };
  if (st.status === "done") return {
    t: "готов",
    c: "var(--pos,#3fb950)",
    run: false
  };
  if (st.status === "error") return {
    t: "ошибка",
    c: "var(--warn)",
    run: false
  };
  const lt = st.live_tool;
  if (lt === "web_search" || lt === "semantic_search") return {
    t: "ищет",
    c: "var(--accent)",
    run: true
  };
  if (lt === "read_url") return {
    t: `читает · ${st.n_reads || 0} стр`,
    c: "var(--accent)",
    run: true
  };
  if (lt === "run_sql") return {
    t: "запрос к БД",
    c: "var(--accent)",
    run: true
  };
  if (st.live_phase === "think") return {
    t: "обдумывает",
    c: "var(--accent)",
    run: true
  };
  return {
    t: "работает",
    c: "var(--accent)",
    run: true
  };
}

