// ─── Дела ────────────────────────────────────────────────────────────────────
// Одно окно на «Базу знаний» и «Отзывы»: в деле документы и жалобы вперемешку.
// Дело можно открыть команде и вести вместе, к каждому материалу — комментарий,
// разбор моделью, выгрузка в Excel и Word.
// Жалоба дела — в виде карточки ленты: та же разметка, те же признаки
const rvCaseCard = it => {
  const r = it.review || {};
  return {
    url: it.url,
    date: r.date,
    bank: r.bank,
    city: r.city,
    product: r.product,
    source: r.source,
    text: it.title || "",
    ann: r.summary || r.issue ? {
      summary: r.summary,
      quote: r.quote,
      esc: r.esc,
      esc_to: r.esc_to || [],
      vulnerable: r.vulnerable || [],
      no_consent: r.no_consent,
      amount: r.amount
    } : null,
    themes: r.issue_label ? [{
      key: r.issue,
      label: r.issue_label,
      short: r.issue_label,
      risk: r.risk
    }] : []
  };
};

