function parseHash() {
  const h = (location.hash || "").slice(1);
  const qi = h.indexOf("?");
  let p = qi >= 0 ? h.slice(0, qi) : h,
    prm = {};
  if (qi >= 0) {
    try {
      prm = Object.fromEntries(new URLSearchParams(h.slice(qi + 1)).entries());
    } catch {}
  }
  if (p === "sber") p = "market";
  if (p === "quality") p = "sources"; // вкладка «Качество» убрана — техчасть на «Источниках»
  return {
    p,
    prm
  };
}
